INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('death_funeral', 'state', '«إِنَّ لِلَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى، فَلْتَصْبِرْ وَلْتَحْتَسِبْ»', 'Waarlijk, aan Allaah behoort wat Hij neemt en aan Hem behoort wat Hij geeft, en alles heeft bij Hem een vastgestelde termijn; wees dus geduldig en reken op de beloning.', 'Indeed to Allaah belongs what He took and to Him belongs what He gave, and everything with Him has an appointed term; so be patient and hope for reward.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التعزية', 'gelegenheid', 'occasion', 1, 221),('death_funeral', 'state', '«السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ»', 'Vrede zij met jullie, bewoners van deze verblijfplaatsen, gelovigen en moslims. Waarlijk, wij zullen ons — als Allaah het wil — bij jullie voegen. Ik vraag Allaah om welzijn voor ons en voor jullie.', 'Peace be upon you, people of these abodes, believers and Muslims. Indeed, if Allaah wills, we shall join you. I ask Allaah for wellbeing for us and for you.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء زيارة القبور', 'gelegenheid', 'occasion', 1, 222),('travel', 'place', '«بِسْمِ اللَّهِ»، فَإِذَا اسْتَوَى عَلَيْهَا قَالَ: «الْحَمْدُ لِلَّهِ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، الْحَمْدُ لِلَّهِ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي، فَإِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ»', 'In de Naam van Allaah — en eenmaal gezeten: Alle lof zij Allaah. Verheven is Degene Die dit voor ons dienstbaar heeft gemaakt, terwijl wij het niet hadden kunnen bedwingen, en waarlijk, tot onze Heer keren wij terug. Alle lof zij Allaah (3x), Allaah is de Grootste (3x). Verheven bent U; ik heb mijzelf onrecht aangedaan, vergeef mij dus, want niemand vergeeft de zonden behalve U.', 'In the Name of Allaah — and once seated: All praise is for Allaah. Glory be to the One who subjected this to us, for we could never have subdued it, and indeed to our Lord we shall return. Praise be to Allaah (3x), Allaah is the Greatest (3x). Glory be to You; I have wronged myself, so forgive me, for none forgives sins except You.', '', '', '', 'الفضل منصوص: يعجب الرب من عبده إذا سأله المغفرة موقنا أنه لا يغفر الذنوب غيره.', 'De verdienste is uitdrukkelijk: de Heer verwondert Zich over Zijn dienaar wanneer hij om vergeving vraagt, overtuigd dat niemand anders de zonden vergeeft.', 'The merit is stated: the Lord marvels at His servant when he asks forgiveness, certain that none other forgives sins.', 'دعاء ركوب الدابة أو المركوب', 'gelegenheid', 'occasion', 1, 223),('travel', 'place', '«اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ، اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمَنْظَرِ، وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ»', 'Allaah is de Grootste (3x). Verheven is Degene Die dit voor ons dienstbaar heeft gemaakt, terwijl wij het niet hadden kunnen bedwingen, en waarlijk, tot onze Heer keren wij terug. O Allaah, wij vragen U op deze reis van ons om vroomheid en godsvrees, en om daden waarover U tevreden bent. O Allaah, maak deze reis licht voor ons en vouw haar afstand voor ons op. O Allaah, U bent de Metgezel op de reis en de Plaatsvervanger bij het gezin. O Allaah, ik zoek toevlucht bij U tegen de ontberingen van de reis, tegen een bedroevend schouwspel en tegen een slechte terugkeer in bezit en gezin.', 'Allaah is the Greatest (3x). Glory be to the One who subjected this to us, for we could never have subdued it, and indeed to our Lord we shall return. O Allaah, we ask You on this journey of ours for righteousness and piety, and for deeds that please You. O Allaah, make this journey easy for us and fold up its distance for us. O Allaah, You are the Companion on the journey and the Guardian over the family. O Allaah, I seek refuge in You from the hardship of travel, from a distressing sight, and from an ill turn of fortune in wealth and family.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء السفر إذا استوى على بعيره خارجا إلى سفر', 'gelegenheid', 'occasion', 1, 224),('travel', 'place', '«آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ»', 'Terugkerend, berouwvol, aanbiddend en onze Heer lovend (toegevoegd bij de terugkeer van de reis).', 'Returning, repenting, worshipping and praising our Lord (added upon returning from travel).', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا رجع قالهن وزاد فيهن', 'gelegenheid', 'occasion', 1, 225),('travel', 'place', '«أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ»', 'Ik vertrouw jouw geloof, jouw toevertrouwde zaken en de afsluiting van jouw daden aan Allaah toe (afscheid van de reiziger).', 'I entrust to Allaah your religion, your trusts, and the final outcome of your deeds (bidding farewell to the traveller).', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'توديع المقيم للمسافر', 'gelegenheid', 'occasion', 1, 226),('travel', 'place', '«أَسْتَوْدِعُكُمُ اللَّهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ»', 'Ik vertrouw jullie toe aan Allaah, bij Wie geen toevertrouwd goed verloren gaat (de reiziger tot de achterblijvers).', 'I entrust you to Allaah, with whom no trusts are ever lost (the traveller to those staying behind).', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء المسافر لمن يودّعه', 'gelegenheid', 'occasion', 1, 227),('drought', 'state', '«اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا»', 'O Allaah, schenk ons regen; o Allaah, schenk ons regen; o Allaah, schenk ons regen.', 'O Allaah, give us rain; O Allaah, give us rain; O Allaah, give us rain.', 'قاله النبي صلى الله عليه وسلم على المنبر في خطبة الجمعة لما شكا إليه الأعرابي هلاك المال وجوع العيال، فيدعى به في خطبة الجمعة وفي كل حال، رافعا يديه، مكررا ثلاثا.', 'De Profeet (vrede en zegeningen zij met hem) zei het op de preekstoel in de vrijdagkhutbah toen de bedoeïen bij hem klaagde over het verlies van bezit en de honger van de mensen.', 'The Prophet (peace and blessings be upon him) said it on the pulpit in the Friday khutbah when the bedouin complained of loss of wealth and people''s hunger.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء الاستسقاء', 'rampspoed', 'calamity', 1, 228),('drought', 'state', '«اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا، مَرِيئًا مَرِيعًا، نَافِعًا غَيْرَ ضَارٍّ، عَاجِلًا غَيْرَ آجِلٍ»', 'O Allaah, begiet ons met een reddende regen: aangenaam, vruchtbaar en voordelig, niet schadelijk; spoedig en niet uitgesteld.', 'O Allaah, water us with a saving rain: wholesome, fertile and beneficial, not harmful; soon and not delayed.', 'يقال في صلاة الاستسقاء وخطبتها وفي عموم الدعاء عند الجدب؛ وفي الحديث: فأُطبقت عليهم السماء.', 'Zegt men in het regengebed en zijn khutbah en in algemene smeekbede bij droogte; in de hadieth: de hemel sloot zich boven hen.', 'Said in the rain prayer and its khutbah and in general supplication during drought; in the hadeeth: the sky closed over them.', 'الأجر مبين في القصة: «فأطبقت عليهم السماء» غيثا.', 'De beloning is toegelicht in het verhaal: ''de hemel sloot zich boven hen'' met regen.', 'The reward is explained in the account: ''the sky closed over them'' with rain.', 'ومن أدعية الاستسقاء', 'rampspoed', 'calamity', 1, 229),('drought', 'state', '«اللَّهُمَّ اسْقِ عِبَادَكَ وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْيِ بَلَدَكَ الْمَيِّتَ»', 'O Allaah, geef Uw dienaren en Uw vee te drinken, spreid Uw barmhartigheid uit en breng Uw dode land tot leven.', 'O Allaah, give drink to Your servants and Your livestock, spread Your mercy, and revive Your dead land.', 'من ألفاظ الاستسقاء الجامعة؛ يتوسل فيه إلى الله بعموم رحمته وحاجة الخلق كلهم حتى البهائم.', 'Een van de omvattende bewoordingen van de istisqaa''; men wendt zich daarin tot Allaah via Zijn algemene barmhartigheid en de behoefte van alle schepselen, zelfs het vee.', 'One of the comprehensive wordings of istisqaa''; in it one turns to Allaah through His general mercy and the need of all creatures, even the livestock.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ومنها', 'rampspoed', 'calamity', 1, 230),('drought', 'state', 'خرج النبي صلى الله عليه وسلم إلى المصلى متواضعا متذللا، فاستقبل القبلة، وحوّل رداءه، وصلى ركعتين، ودعا', 'De Profeet (vrede en zegeningen zij met hem) ging nederig en deemoedig naar de gebedsplaats, wendde zich naar de qiblah, keerde zijn mantel binnenstebuiten en bad twee rak3ah.', 'The Prophet (peace and blessings be upon him) went out humbly to the prayer-ground, faced the qiblah, turned his cloak inside out, and prayed two rak3ahs.', 'يخرج الإمام بالناس إلى مصلى مكشوف بتذلل وخشوع، فيخطب ويكثر الاستغفار والدعاء، ثم يستقبل القبلة ويحوّل رداءه فيجعل ما على يمينه على شماله تفاؤلا بتحول الحال، ويحوّل الناس أرديتهم، ويصلي ركعتين كصلاة العيد.', 'De imaam trekt met de mensen naar een open gebedsplaats in nederigheid en deemoed, houdt een khutbah met veel istighfaar en smeekbede, wendt zich dan naar de qiblah en keert zijn mantel binnenstebuiten.', 'The imaam goes out with the people to an open prayer-ground in humility and submission, delivers a khutbah with much istighfaar and supplication, then faces the qiblah and turns his cloak inside out.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'صفة صلاة الاستسقاء', 'rampspoed', 'calamity', 1, 231),('drought', 'state', 'كان النبي صلى الله عليه وسلم لا يرفع يديه في شيء من دعائه إلا في الاستسقاء؛ فإنه يرفع حتى يُرى بياض إبطيه', 'Bij geen enkele smeekbede hief hij zijn handen zó hoog als bij het regengebed, totdat het wit van zijn oksels zichtbaar werd.', 'In no supplication did he raise his hands so high as in praying for rain, until the whiteness of his armpits was visible.', 'فيبالغ الداعي في الاستسقاء برفع يديه أكثر من سائر الدعاء، ويجعل ظاهر كفيه إلى السماء كما في رواية مسلم.', 'De smekende overdrijft in het regengebed door zijn handen hoger op te heffen dan bij andere smeekbede, en keert de rug van zijn handpalmen naar de hemel zoals in de overlevering.', 'The supplicant is emphatic in the rain prayer, raising his hands higher than in other supplication, and turns the backs of his palms to the sky as in the narration.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'المبالغة في رفع اليدين', 'rampspoed', 'calamity', 1, 232),('drought', 'state', 'يجعل ظهور كفيه إلى السماء في دعاء الاستسقاء', 'Bij het regengebed wees hij met de rug van zijn handen naar de hemel — bij het vragen om afwending van rampspoed.', 'In praying for rain he pointed with the backs of his hands to the sky — when asking for calamity to be lifted.', 'قال أهل العلم: هذا في سؤال رفع البلاء ودفعه، وأما سؤال حصول الشيء فببطون الكفين كما في عموم الدعاء.', 'De geleerden zeiden: dit geldt bij het vragen om afwending en opheffing van rampspoed; het vragen om het verkrijgen van iets gebeurt met de palmen (naar boven) zoals in de algemene smeekbede.', 'The scholars said: this is for asking the lifting and repelling of calamity; asking for the attaining of something is with the palms (upward) as in general supplication.', 'لم يرد فيه أجر مخصوص، وهو من كمال الاقتداء بهيئته صلى الله عليه وسلم.', 'Er is geen specifieke beloning voor overgeleverd, het behoort tot de volmaaktheid van het navolgen van zijn houding (vrede en zegeningen zij met hem).', 'No specific reward is reported, it is part of the perfection of following his posture (peace and blessings be upon him).', 'ومن هيئته ﷺ في دعاء الاستسقاء: قلب الكفين', 'rampspoed', 'calamity', 1, 233),('drought', 'state', 'قال الله تعالى عن نوح عليه السلام: ﴿فَقُلْتُ اسْتَغْفِرُوا رَبَّكُمْ إِنَّهُ كَانَ غَفَّارًا ۝١٠ يُرْسِلِ السَّمَاءَ عَلَيْكُم مِّدْرَارًا﴾', 'Vertaling van de betekenis: Vraag jullie Heer om vergeving; waarlijk, Hij is Vergevensgezind. Hij zal de hemel in overvloed over jullie laten regenen... [Noeh 10-12]; istighfaar is dus een sleutel tot regen en voorziening.', 'Meaning: Seek your Lord''s forgiveness; indeed He is Most Forgiving. He will send the sky upon you in showers... [Nooh 10-12]; istighfaar is thus a key to rain and provision.', 'فمن أعظم أسباب نزول الغيث الاستغفار والتوبة من الذنوب؛ فيُكثر منه الإمام والناس قبل الدعاء ومعه.', 'Een van de grootste oorzaken voor het neerdalen van regen is istighfaar en berouw van zonden; de imaam en de mensen vermeerderen dit vóór en tijdens de smeekbede.', 'One of the greatest causes for rain to descend is istighfaar and repentance from sins; the imaam and the people increase it before and during the supplication.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستغفار للاستسقاء', 'rampspoed', 'calamity', 1, 234),('drought', 'state', 'كَانَ عُمَرُ إِذَا قُحِطُوا اسْتَسْقَى بِالْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ فَقَالَ: «اللَّهُمَّ إِنَّا كُنَّا نَتَوَسَّلُ إِلَيْكَ بِنَبِيِّنَا فَتَسْقِينَا، وَإِنَّا نَتَوَسَّلُ إِلَيْكَ بِعَمِّ نَبِيِّنَا فَاسْقِنَا»، قَالَ: فَيُسْقَوْنَ', 'O Allaah, wij plachten ons tot U te wenden via (de smeekbede van) onze Profeet en U gaf ons regen; nu wenden wij ons tot U via de oom van onze Profeet — geef ons dus regen. (En dan werd hun regen geschonken.)', 'O Allaah, we used to turn to You through (the supplication of) our Prophet and You gave us rain; now we turn to You through the uncle of our Prophet — so give us rain. (And they would be given rain.)', 'فيه أن المشروع التوسل بدعاء الرجل الصالح الحي: يُطلب منه أن يدعو الله، لا التوسل بذوات الأموات ولا الدعاء عند القبور. وذكر الحافظ ابن حجر في فتح الباري (2/497) أن العباس رضي الله عنه قام فقال: «اللهم إنه لم ينزل بلاء إلا بذنب، ولم يُكشف إلا بتوبة، وقد توجه القوم بي إليك لمكاني من نبيك، وهذه أيدينا إليك بالذنوب، ونواصينا إليك بالتوبة، فاسقنا الغيث»، قال: فأرخت السماء مثل الجبال حتى أخصبت الأرض وعاش الناس؛ فهذا نص دعاء الصحابي المتوسَّل بدعائه.', 'Hierin ligt dat het voorgeschrevene is zich te wenden via de smeekbede van de levende rechtschapen man: men vraagt hem tot Allaah te bidden, niet het zich wenden via de overledenen.', 'In it lies that what is prescribed is turning through the supplication of a living righteous man: one asks him to pray to Allaah, not turning through the deceased.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التوسل بدعاء الصالحين للاستسقاء', 'rampspoed', 'calamity', 1, 235),('floods', 'state', '«اللَّهُمَّ حَوَالَيْنَا وَلَا عَلَيْنَا، اللَّهُمَّ عَلَى الْآكَامِ وَالظِّرَابِ وَبُطُونِ الْأَوْدِيَةِ وَمَنَابِتِ الشَّجَرِ»', 'O Allaah, om ons heen en niet op ons. O Allaah, op de heuvels, de hoogten, de beddingen van de valleien en de groeiplaatsen van de bomen.', 'O Allaah, around us and not upon us. O Allaah, upon the hills, the high grounds, the valley beds and the places where trees grow.', 'قاله النبي صلى الله عليه وسلم على المنبر لما شُكي إليه تهدم البناء وغرق المال، وأشار بيده إلى السحاب، فيُدعى به عند الأمطار الجارفة والسيول، ولا يُدعى برفع المطر مطلقا؛ بل بصرفه إلى مواضع النفع، أدبا مع النعمة.', 'De Profeet (vrede en zegeningen zij met hem) zei het op de preekstoel toen bij hem werd geklaagd over instortende gebouwen en verdronken bezit, en hij wees met zijn hand naar de wolken.', 'The Prophet (peace and blessings be upon him) said it on the pulpit when the collapse of buildings and drowning of wealth was complained of to him, pointing with his hand at the clouds.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند خوف ضرر المطر', 'rampspoed', 'calamity', 1, 236),('floods', 'state', 'كان صلى الله عليه وسلم إذا رأى مخيلة أقبل وأدبر وتغير وجهه، فإذا أمطرت سُرّي عنه، وقال: «ما أدري لعله كما قال قوم: ﴿فَلَمَّا رَأَوْهُ عَارِضًا مُّسْتَقْبِلَ أَوْدِيَتِهِمْ﴾»', 'Bij dreigende luchten was zijn onrust zichtbaar; regende het, dan ontspande hij — hij zei: misschien is het zoals het volk van 3aad zei: dit is een wolk die ons regen brengt.', 'At threatening skies his unease showed; when it rained he relaxed — saying: perhaps as the people of 3aad said: this is a cloud bringing us rain.', 'فالتطبيق عند تلبد الغيوم المخوفة: الوجل من العذاب وسؤال الله خيرها بدعاء الريح المتقدم، لا الاسترسال في الغفلة.', 'De toepassing bij het samenpakken van dreigende wolken: vrees voor de bestraffing en Allaah om het goede ervan vragen met de eerder genoemde windsmeekbede, niet het zich zorgeloos overgeven.', 'The application when threatening clouds gather: fearing the punishment and asking Allaah for its good with the aforementioned wind supplication, not heedless indulgence.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند رؤية الغيم المخوف', 'rampspoed', 'calamity', 1, 237),('poverty', 'state', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْجُوعِ؛ فَإِنَّهُ بِئْسَ الضَّجِيعُ، وَأَعُوذُ بِكَ مِنَ الْخِيَانَةِ؛ فَإِنَّهَا بِئْسَتِ الْبِطَانَةُ»', 'O Allaah, ik zoek toevlucht bij U tegen de honger, want het is een slechte bedgenoot; en ik zoek toevlucht bij U tegen verraad, want het is een slechte innerlijke metgezel.', 'O Allaah, I seek refuge in You from hunger, for it is a wretched bedfellow; and I seek refuge in You from treachery, for it is a wretched inner companion.', 'يقوله من خاف الجوع أو نزل به، ويجعله من دعائه الراتب؛ فإن النبي صلى الله عليه وسلم كان يدعو بهؤلاء الكلمات.', 'Zegt wie honger vreest of erdoor getroffen wordt, en men maakt het tot zijn vaste smeekbede; want de Profeet (vrede en zegeningen zij met hem) smeekte hiermee.', 'Said by whoever fears hunger or is struck by it, making it one of one''s regular supplications; for the Prophet (peace and blessings be upon him) supplicated with these.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من الجوع', 'rampspoed', 'calamity', 1, 238),('poverty', 'state', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْفَقْرِ وَالْقِلَّةِ وَالذِّلَّةِ، وَأَعُوذُ بِكَ مِنْ أَنْ أَظْلِمَ أَوْ أُظْلَمَ»', 'O Allaah, ik zoek toevlucht bij U tegen armoede, schaarste en vernedering, en ik zoek toevlucht bij U ertegen dat ik onrecht doe of dat mij onrecht wordt aangedaan.', 'O Allaah, I seek refuge in You from poverty, scarcity and humiliation, and I seek refuge in You from wronging or being wronged.', 'يدعو به من ضاق رزقه، مع الأخذ بأسباب الكسب؛ فالدعاء لا يغني عن السعي.', 'Smeekt wie zijn voorziening nauw wordt, met het nemen van de middelen tot verwerving; want de smeekbede vervangt het streven niet.', 'Supplicated by whoever''s provision is straitened, while taking the means of earning; for supplication does not replace effort.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الاستعاذة من الفقر', 'rampspoed', 'calamity', 1, 239),('poverty', 'state', '«اللَّهُمَّ اجْعَلْ رِزْقَ آلِ مُحَمَّدٍ قُوتًا»', 'O Allaah, maak de voorziening van de familie van Muhammad toereikend levensonderhoud.', 'O Allaah, make the provision of the family of Muhammad sufficient sustenance.', 'فيه أن الجائع والمقلّ يسأل الله الكفاف الذي يقوم به بدنه ودينه، ويرضى به إذا أعطيه؛ فهو دعاء النبي صلى الله عليه وسلم لأهل بيته.', 'Hierin ligt dat de hongerige en de behoeftige Allaah om het toereikende vragen dat zijn lichaam en zijn geloof staande houdt, en er tevreden mee is als het hem gegeven wordt; het is de smeekbede van de Profeet (vrede en zegeningen zij met hem).', 'In it lies that the hungry and the poor ask Allaah for the sufficiency that sustains body and religion, content with it when granted; it is the supplication of the Prophet (peace and blessings be upon him).', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'سؤال الكفاف', 'rampspoed', 'calamity', 1, 240);